<script setup lang="ts">import {onMounted,ref} from 'vue';import {getStudio,type StudioPayload} from './content-studio-api';const payload=ref<StudioPayload|null>(null);onMounted(async()=>payload.value=await getStudio());const labels:Record<string,string>={'missing-english':'缺英文名','missing-image':'没有图片','missing-summary':'没有简介','overnight-unknown':'过夜状态未知','english-status':'英文状态异常','geometry-integrity':'路线数据完整性'};</script><template><div v-if="payload" class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">需要处理</p><h1>慢慢补齐，不阻塞日常维护</h1><p>错误会阻止发布；提醒可以确认后继续。</p></div></div><div class="issue-summary"><span v-for="(count,key) in payload.dashboard.issueCounts"><b>{{count}}</b>{{labels[key]||key}}</span></div><div class="issue-list"><RouterLink v-for="issue in payload.dashboard.issues" :to="issue.href||'/studio'" :class="issue.level"><strong>{{issue.level==='error'?'必须处理':'提醒'}}</strong><span>{{issue.message}}</span></RouterLink></div></div></template>
